import java.util.*;
record Event(int year,String name){}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();List<Event> events=new ArrayList<>();for(int i=0;i<n;i++)events.add(new Event(s.nextInt(),s.next()));events.sort(Comparator.comparingInt(Event::year).thenComparing(Event::name));for(Event e:events)System.out.println(e.year()+":"+e.name());int oak=0,sun=0,openjdk=0;for(Event e:events){if(e.year()<1995)oak++;else if(e.year()<=2005)sun++;else openjdk++;}System.out.println("oak="+oak);System.out.println("sun="+sun);System.out.println("openjdk="+openjdk);}}

